package dev.pocketengine.features.plugins;

import static org.junit.Assert.*;
import android.app.Application;
import android.content.ContentValues;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.features.FeatureHost;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.*;
import org.json.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import org.robolectric.annotation.SQLiteMode;

/** Real original storage review/intent/worker deletes only the exact settled native MCP copy.
 * Unknown process/business effects remain protected; no auto eviction or second cache authority. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
@SQLiteMode(SQLiteMode.Mode.NATIVE)
public final class McpLocalCacheNativeTest {
    private static String selected(String operation){return "native_cache:mcp_copy:"+operation;}
    private static Path copy(McpLocalDiscoveryReviewTest.Fixture f,String operation){return f.android.getFilesDir().toPath().resolve("local-development/mcp-discovery-copies").resolve(operation);}
    private static JSONObject row(McpLocalDiscoveryReviewTest.Fixture f,String operation)throws Exception{JSONObject inventory=f.local.ownerStorageInventoryForHost(new RunControl());JSONArray rows=inventory.getJSONArray("groups");for(int i=0;i<rows.length();i++)if(selected(operation).equals(rows.getJSONObject(i).getString("id")))return rows.getJSONObject(i);throw new AssertionError("missing original copy inventory "+operation+": "+inventory);}
    private static String discover(McpLocalDiscoveryOwnerTest.Fixture x)throws Exception{String id=x.confirm(x.prepare()).getString("taskId");assertEquals("completed",x.finished(id).getString("status"));return id;}
    private static JSONObject finished(FeatureHost host,String task)throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(12);JSONObject result=null;while(System.nanoTime()<until){result=host.ownerStorageCleanupForOwner(task);if(result.optString("status").matches("completed|failed|reconciling"))return result;Thread.sleep(20);}throw new AssertionError("original storage worker did not settle: "+result);}
    private static String book(McpLocalInvocationNativeTest.Fixture x)throws Exception{StringBuilder kept=new StringBuilder();try(android.database.Cursor rows=x.db().rawQuery("SELECT body FROM task_output_chunks ORDER BY rowid",null)){while(rows.moveToNext())kept.append(rows.getString(0));}return kept.toString();}
    private static String clean(McpLocalDiscoveryReviewTest.Fixture f,FeatureHost host,String operation)throws Exception{var review=f.local.reviewOwnerStorageForHost(Set.of(selected(operation)),new RunControl());assertFalse(review.metadata().getBoolean("automaticRetry"));var confirmed=review.confirm();String id=confirmed.actionId();host.submitOwnerStorageCleanupForOwner(confirmed);assertEquals("completed",finished(host,id).getString("status"));assertThrows(Exception.class,()->host.submitOwnerStorageCleanupForOwner(confirmed));return id;}
    @Test public void unboundOriginalTaskLedgerShowsTheMcpRootAsProtectedAndCannotReviewItForDeletion()throws Exception{try(var f=new McpLocalDiscoveryReviewTest.Fixture()){String id=UUID.randomUUID().toString();Files.createDirectories(copy(f,id));Files.write(copy(f,id).resolve("unattributed"),new byte[]{1});JSONArray groups=f.local.ownerStorageInventoryForHost(new RunControl()).getJSONArray("groups");JSONObject protectedRoot=null;for(int i=0;i<groups.length();i++)if("protected:mcp-discovery-copies".equals(groups.getJSONObject(i).optString("id")))protectedRoot=groups.getJSONObject(i);assertNotNull(protectedRoot);assertFalse(protectedRoot.getBoolean("cleanable"));assertThrows(SecurityException.class,()->f.local.reviewOwnerStorageForHost(Set.of(selected(id)),new RunControl()));assertTrue(Files.exists(copy(f,id).resolve("unattributed")));assertEquals(0,f.tasks.list().length());assertEquals(0,f.runtime.environmentManager().describe(f.pack).getInt("activeLeases"));}}
    @Test public void completedDiscoveryCopyCanBeExplicitlyRemovedWithoutChangingOriginalSourceFactsOrPendingInstallReview()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String id=discover(x);JSONObject original=x.f.tasks.ownerMcpDiscoveryForOwner(id);String facts=x.f.tasks.completedOwnerMcpDiscoveryForInstallForOwner(id).factsDigest(),log=x.f.runtime.query(x.ref(id)).json().getString("stderr");JSONObject install=x.owner.mcp("prepareLocalMcpInstall",new JSONObject().put("taskId",id).put("tools",new JSONArray().put("lookup")));assertTrue(row(x.f,id).toString(),row(x.f,id).getBoolean("cleanable"));String cleanup=clean(x.f,x.host,id);assertFalse(Files.exists(copy(x.f,id)));assertEquals(facts,x.f.tasks.completedOwnerMcpDiscoveryForInstallForOwner(id).factsDigest());assertEquals(original.toString(),x.f.tasks.ownerMcpDiscoveryForOwner(id).toString());assertEquals(log,x.f.runtime.query(x.ref(id)).json().getString("stderr"));assertEquals(x.f.config.getString("expectedSourceDigest"),x.f.digest());JSONObject installed=x.owner.mcp("confirmLocalMcpInstall",new JSONObject().put("reviewId",install.getString("reviewId")).put("reviewDigest",install.getString("reviewDigest")));assertFalse(installed.getBoolean("enabled"));assertEquals(0,installed.getJSONArray("grants").length());assertEquals(cleanup,x.f.tasks.get(id,false).getJSONObject("nativeMcpCacheRetirements").getJSONObject(id).getString("cleanupActionId"));assertFalse(x.f.tasks.nativeExecutionCacheDispositionForOwner("mcp_copy",id).disposable);}}
    @Test public void successfulToolCopyDeletesOnlyUnpublishedRelativeWritesAndRetainsOriginalBookResultTaskAndInstallation()throws Exception{try(var x=new McpLocalInvocationNativeTest.Fixture();var call=x.capturedCall()){JSONObject result=call.invoke();call.journal.finishOperation(call.operation,result);assertEquals("response_received",result.getString("status"));assertTrue(Files.exists(x.copy(call.operation).resolve("START_EFFECT")));assertTrue(Files.exists(x.copy(call.operation).resolve("RPC_EFFECT")));JSONObject before=call.record().publicReceiptForHost();String installation=x.f.plugins.snapshot().toString(),log=x.f.runtime.query(call.record().referenceForHost()).json().getString("stderr");String book=book(x);assertTrue(book.contains("Actual local result"));String cleanup=clean(x.f,x.host,call.operation);assertFalse(Files.exists(x.copy(call.operation)));assertEquals(installation,x.f.plugins.snapshot().toString());assertEquals(before.toString(),call.record().publicReceiptForHost().toString());assertEquals(log,x.f.runtime.query(call.record().referenceForHost()).json().getString("stderr"));assertEquals(book,book(x));assertTrue(Files.isRegularFile(x.f.android.getFilesDir().toPath().resolve("local-development/checkouts").resolve(x.f.checkout).resolve("files/server.py")));assertEquals("completed",x.host.ownerStorageCleanupForOwner(cleanup).getString("status"));assertFalse(Files.exists(x.copy(call.operation)));}}
    @Test public void lostBusinessReplyStaysProtectedEvenAfterProcessCleanupUntilOriginalOwnerExplicitlyReconciles()throws Exception{try(var x=new McpLocalInvocationNativeTest.Fixture("lost");var call=x.call()){JSONObject receipt=call.invoke();call.journal.finishOperation(call.operation,receipt);assertEquals("unknown",receipt.getString("status"));assertTrue(receipt.getJSONObject("nativeMcp").getBoolean("processSettled"));assertFalse(row(x.f,call.operation).getBoolean("cleanable"));assertThrows(Exception.class,()->x.f.local.reviewOwnerStorageForHost(Set.of(selected(call.operation)),new RunControl()));x.f.tasks.resolveOperation(call.task,call.operation,"occurred");assertTrue(row(x.f,call.operation).toString(),row(x.f,call.operation).getBoolean("cleanable"));String before=call.record().publicReceiptForHost().toString();clean(x.f,x.host,call.operation);assertEquals(before,call.record().publicReceiptForHost().toString());assertEquals("unknown",call.record().publicReceiptForHost().getJSONObject("nativeMcp").getString("rpcEffectStatus"));assertFalse(call.record().publicReceiptForHost().getBoolean("automaticallyVerified"));}}
    @Test public void liveOriginalPipeAndLeaseCannotBeCleanedWhileAwaitingTheSameToolReply()throws Exception{try(var x=new McpLocalInvocationNativeTest.Fixture("block");var call=x.call()){ExecutorService executor=Executors.newSingleThreadExecutor();try{Future<JSONObject> live=executor.submit(call::invoke);boolean entered=false;long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(8);while(System.nanoTime()<until){try{if(x.f.runtime.query(call.record().referenceForHost()).json().optString("stderr").contains("CALL_ENTERED")){entered=true;break;}}catch(Exception notPublished){}Thread.sleep(20);}assertTrue(entered);assertFalse(row(x.f,call.operation).getBoolean("cleanable"));assertThrows(Exception.class,()->x.f.local.reviewOwnerStorageForHost(Set.of(selected(call.operation)),new RunControl()));assertTrue(Files.exists(x.copy(call.operation)));x.host.observeLocalMcpInvocationsForOwner(call.task,true);try{live.get(10,TimeUnit.SECONDS);}catch(ExecutionException stopped){assertTrue(stopped.getCause() instanceof InterruptedException||stopped.getCause() instanceof SecurityException);}assertTrue(Files.exists(x.copy(call.operation)));}finally{call.control.cancel();executor.shutdownNow();}}}
    @Test public void changedCopyAfterReviewFailsClosedAndKeepsOriginalRetirementBoundToThatCleanup()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String id=discover(x);var review=x.f.local.reviewOwnerStorageForHost(Set.of(selected(id)),new RunControl());var confirmed=review.confirm();Path added=copy(x.f,id).resolve("later-unreviewed");Files.write(added,"keep new relative file".getBytes(StandardCharsets.UTF_8));x.host.submitOwnerStorageCleanupForOwner(confirmed);assertEquals("reconciling",finished(x.host,confirmed.actionId()).getString("status"));assertTrue(Files.exists(added));assertFalse(x.f.tasks.nativeExecutionCacheDispositionForOwner("mcp_copy",id).disposable);assertThrows(Exception.class,()->x.f.local.reviewOwnerStorageForHost(Set.of(selected(id)),new RunControl()));assertThrows(Exception.class,()->x.host.submitOwnerStorageCleanupForOwner(confirmed));JSONObject observed=x.host.queryOwnerStorageCleanupForOwner(confirmed.actionId(),new RunControl());assertFalse(observed.getBoolean("allTargetsCurrentlyAbsent"));assertFalse(observed.getBoolean("automaticRetry"));assertEquals("completed",x.f.tasks.ownerMcpDiscoveryForOwner(id).getString("status"));}}
    @Test public void unattributedFolderAndUnboundPreparedOperationRemainProtectedWithoutInferringNoChild()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String unknown=UUID.randomUUID().toString();Files.createDirectories(copy(x.f,unknown));Files.write(copy(x.f,unknown).resolve("own-evidence"),new byte[]{1});assertFalse(row(x.f,unknown).getBoolean("cleanable"));assertThrows(Exception.class,()->x.f.local.reviewOwnerStorageForHost(Set.of(selected(unknown)),new RunControl()));var approved=x.f.confirmed();x.f.tasks.beginOwnerMcpDiscoveryForOwner(approved,new RunControl());Files.createDirectories(copy(x.f,approved.actionId()));assertFalse(row(x.f,approved.actionId()).getBoolean("cleanable"));assertThrows(Exception.class,()->x.f.tasks.nativeExecutionCacheDispositionForOwner("mcp_copy",approved.actionId()));assertTrue(Files.exists(copy(x.f,unknown).resolve("own-evidence")));approved.close();}}
    @Test public void missingSessionProofOrOrdinaryExitContractCannotReplaceTheExactPipeCleanupFacts()throws Exception{try(var x=new McpLocalInvocationNativeTest.Fixture();var call=x.call()){JSONObject receipt=call.invoke();call.journal.finishOperation(call.operation,receipt);assertTrue(row(x.f,call.operation).getBoolean("cleanable"));for(String field:new String[]{"processSessionAbsent","resourcesReleased","nativeResultContract"}){JSONObject changed=new JSONObject(receipt.toString());changed.getJSONObject("nativeMcp").getJSONObject("processReceipt").put(field,field.equals("nativeResultContract")?dev.pocketengine.features.local.runtime.NativeProcessSupervisor.EXIT_RESULT_CONTRACT:false);ContentValues values=new ContentValues();values.put("receipt",changed.toString());assertEquals(1,x.db().update("operations",values,"operation_id=? AND task_id=?",new String[]{call.operation,call.task}));assertFalse(field,row(x.f,call.operation).getBoolean("cleanable"));}ContentValues restore=new ContentValues();restore.put("receipt",receipt.toString());assertEquals(1,x.db().update("operations",restore,"operation_id=? AND task_id=?",new String[]{call.operation,call.task}));assertTrue(row(x.f,call.operation).getBoolean("cleanable"));}}
    @Test public void deletingReviewedSymlinkRemovesOnlyItsLinkAndRetainsTheExternalTargetAndSource()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String id=discover(x);Path outside=Files.createTempDirectory("mcp-cache-outside-");Path original=outside.resolve("retain.txt");Files.write(original,"outside is not a cleanup target".getBytes(StandardCharsets.UTF_8));Files.createSymbolicLink(copy(x.f,id).resolve("relative-link"),outside);assertTrue(row(x.f,id).getBoolean("cleanable"));clean(x.f,x.host,id);assertEquals("outside is not a cleanup target",new String(Files.readAllBytes(original),StandardCharsets.UTF_8));assertEquals(x.f.config.getString("expectedSourceDigest"),x.f.digest());}}
    @Test public void explicitOriginalCleanupReleasesTheSixteenCopyCeilingWithoutAutoEvictionOrReplay()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String first=null;for(int i=0;i<16;i++){String id=discover(x);if(first==null)first=id;}assertEquals(16,copy(x.f,first).getParent().toFile().listFiles(java.io.File::isDirectory).length);String refused=x.confirm(x.prepare()).getString("taskId");assertEquals("failed",x.finished(refused).getString("status"));assertFalse(Files.exists(copy(x.f,refused)));assertEquals(16,copy(x.f,first).getParent().toFile().listFiles(java.io.File::isDirectory).length);String original=first;clean(x.f,x.host,first);assertFalse(Files.exists(copy(x.f,original)));assertEquals(15,copy(x.f,first).getParent().toFile().listFiles(java.io.File::isDirectory).length);String next=discover(x);assertNotEquals(first,next);assertTrue(Files.exists(copy(x.f,next)));assertEquals(16,copy(x.f,next).getParent().toFile().listFiles(java.io.File::isDirectory).length);assertEquals("completed",x.f.tasks.ownerMcpDiscoveryForOwner(original).getString("status"));assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));}}
}
